@pytest.mark.parametrize('entry,hidden,exit_code', [('mcp', True, 0), ('mcp', False, 7), ('independent', True, 0), ('scheduled', True, 0)]) def test_venv_runner_has_no_window_before_task_imports(tmp_path, monkeypatch, request, entry, hidden, exit_code): from packages.core import background_jobs as jobs, config from packages.jobs.independent_service import JobStore from packages.jobs import independent_service from packages.mcp import server as mcp from packages.web import server as web from fastapi import FastAPI from fastapi.testclient import TestClient venv_root = tmp_path / 'venv' venv.EnvBuilder(with_pip=False, system_site_packages=True).create(venv_root) # system_site_packages inherits the base installation, not the venv which # is running pytest. Reuse this test interpreter's installed dependencies # explicitly, without installing anything or changing the selected Python. (venv_root / 'Lib/site-packages/test-parent.pth').write_text( '\n'.join(site.getsitepackages()) + '\n', encoding='utf-8') python = str(venv_root / 'Scripts/python.exe') observation = tmp_path / 'runner'; observation.mkdir() helper = Path(__file__).parent / 'helpers/runner_startup_probe.py' customization = venv_root / 'Lib/site-packages/sitecustomize.py' customization.write_text('import runpy;runpy.run_path(' + repr(str(helper.resolve())) + ', init_globals={"OUTPUT_DIRECTORY":' + repr(str(observation)) + '})', encoding='utf-8') monkeypatch.setattr(config, 'load_config', lambda: {'python': python}) monkeypatch.setattr(jobs._sessions, 'get', lambda sid: {'id': sid}) root = tmp_path / 'registry' monkeypatch.setenv('PAN_BACKGROUND_JOBS_DIR', str(root)) # The real runner imports repo code even though command cwd is isolated. repo = Path(__file__).resolve().parents[1] monkeypatch.setattr(jobs, 'PROJECT_ROOT', repo) import subprocess from packages.core.terminal.identity import read_creation_filetime captured = [] from packages.core.terminal.guard import JobObjectGuard owner = JobObjectGuard() def cleanup(): try: _, remaining = owner.terminate_tree(None, timeout=5) assert not remaining finally: assert owner.close() for process, filetime in captured: assert read_creation_filetime(int(process._handle)) == filetime if process.poll() is None: process.kill() process.wait(timeout=5) process._handle.Close() request.addfinalizer(cleanup) original_popen = subprocess.Popen def spawn(*args, **kwargs): import ctypes kwargs['creationflags'] = kwargs.get('creationflags', 0) | 4 process = original_popen(*args, **kwargs) captured.append((process, read_creation_filetime(int(process._handle)))) owner.assign(int(process._handle)) resume = ctypes.WinDLL('ntdll').NtResumeProcess resume.argtypes = [ctypes.c_void_p] resume.restype = ctypes.c_long assert resume(int(process._handle)) == 0 return process monkeypatch.setattr(subprocess, 'Popen', spawn) output = tmp_path / 'payload.json' program = 'import ctypes,json,os,sys;from pathlib import Path;Path(' + repr(str(output)) + ').write_text(json.dumps({"pid":os.getpid(),"prefix":sys.prefix,"cwd":os.getcwd(),"console":bool(ctypes.windll.kernel32.GetConsoleWindow())}));print("owned stdout",flush=True);print("owned stderr",file=sys.stderr,flush=True);sys.exit(' + str(exit_code) + ')' argv = [python, '-c', program] if entry == 'mcp': > app = FastAPI(); app.post('/api/background-jobs')(web.api_background_job_start) ^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E AttributeError: module 'packages.web.server' has no attribute 'api_background_job_start'. Did you mean: 'api_background_job_get'?
